select set_config('lumiscore.catalog_release_receipt','{"rows":[{"key":{"open_library_id":"OL228968A"},"seq":1,"relation":"authors","after_row":{"id":987324001,"name":"John Wyndham","open_library_id":"OL228968A"},"before_row":null},{"key":{"native_identity_key":"nlscale:20261102:ol:OL1911336W"},"seq":2,"relation":"works","after_row":{"id":987124001,"title":"The Day of the Triffids","cover_id":13119475,"author_id":987324001,"work_type":"novel","source_type":"open_library","open_library_id":"OL1911336W","first_publish_year":1951,"native_identity_key":"nlscale:20261102:ol:OL1911336W"},"before_row":null},{"key":{"open_library_edition_id":"OL45002848M"},"seq":3,"relation":"editions","after_row":{"id":987224001,"title":"De Triffids Komen","isbn_10":null,"isbn_13":"9789027432858","work_id":987124001,"cover_id":13119475,"language":"dut","publisher":"Het Spectrum","publish_date":null,"open_library_edition_id":"OL45002848M"},"before_row":null},{"key":{"work_id":987124001,"language":"nl"},"seq":4,"relation":"catalog_work_descriptions","after_row":{"text":"Tijdens een ziekenhuisopname mist Bill Masen een hemelverschijnsel waar bijna iedereen naar kijkt. Wanneer zijn verband afgaat, blijkt een groot deel van de bevolking blind te zijn geworden. De samenleving valt uiteen, terwijl de triffids, planten die zich kunnen verplaatsen en een giftige aanval kunnen uitvoeren, een steeds groter gevaar vormen. Bill probeert zich in deze veranderde wereld staande te houden. Het verhaal onderzoekt hoe mensen zich organiseren wanneer vertrouwde bescherming en regels wegvallen.","work_id":987124001,"evidence":[{"note":"ExactDutchSpectrumprint9789027432858/294p full1951novel. JohnWyndham sole originalnovelist; MarcelBattin translator/othereditioncredit and AndyBridge designer not coauthors. No adaptation/film or anthology substitution.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p107631296"],"reference":"new-work-dossier-readings-025.json#12","checked_at":"2026-11-02T22:25:40.674Z"},{"type":"original_substantive_source_review","review":"content-review-001.json","sources":["https://www.bol.com/nl/nl/f/de-triffids-komen/33724439/","https://www.booksinbelgium.be/nl/b/wyndham-triffids-komen-9789027432858","https://openlibrary.org/works/OL1911336W","https://data.bibliotheken.nl/id/nbt/p107631296"]},{"type":"explicit_contributor_roles","credits":[{"name":"Marcel Battin","role":"translator/other-edition credit; not original novelist","source":"https://openlibrary.org/authors/OL8007250A"},{"name":"Andy Bridge","role":"cover designer on source; not novelist","source":"https://openlibrary.org/authors/OL8007853A"}],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"type":"cover_front_review","sha256":"9f876d5b51b9e641b94ea74a0fae19b9074100a4d238aea21e2079d426e3d11c","cover_id":13119475,"reference":"cover-semantic-review-011.json","limitation":"Front title/author and source-edition binding; no barcode or exact printing-year claim."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.bol.com/nl/nl/f/de-triffids-komen/33724439/","reviewed_at":"2026-11-02T22:25:40.674+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-025","review_status":"approved","bound_author_id":987324001},"before_row":null},{"key":{"edition_id":987224001},"seq":5,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987124001,"evidence":[{"note":"ExactDutchSpectrumprint9789027432858/294p full1951novel. JohnWyndham sole originalnovelist; MarcelBattin translator/othereditioncredit and AndyBridge designer not coauthors. No adaptation/film or anthology substitution.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p107631296"],"reference":"new-work-dossier-readings-025.json#12","checked_at":"2026-11